# -*- coding: utf-8 -*-
# Pattern data for SUBNET//GHOSTLINE
# cell = (row, chan, note, inst, vol, fx, param); note int or 'off'
# chan: 0 kick 1 snr 2 clap 3 hhc 4 hho 5 crash 6 bass 7 stab 8 lead
#       9 lead2 10 pno 11 pno2 12 fxtom 13 stab2 14 lead3(pno rhy) 15 pad

def K(row, vol=52, inst=1):  return (row,0,'C-4',inst or 1,vol,0,0)
def SN(row, vol=36):         return (row,1,'C-4',2,vol,0,0)
def CN(row, vol=30):         return (row,2,'C-4',3,vol,0,0)
def H(row, vol=18, open_=False, inst=4):
    return (row,3,'C-4',5 if open_ else 4,vol,0,0)
def CR(row, vol=24):         return (row,5,'C-4',6,vol,0,0)
def B(row, note, inst=8, vol=44): return (row,6,note,inst,vol,0,0)
def ST(row, note, inst=11, vol=34, chan=7, fx=0, fp=0): return (row,chan,note,inst,vol,fx,fp)
def L1(row, note, inst=14, vol=24, fx=0, fp=0): return (row,8,note,inst,vol,fx,fp)
def L2(row, note, inst=15, vol=24, fx=0, fp=0): return (row,9,note,inst,vol,fx,fp)
def L3(row, note, inst=15, vol=17, fx=0, fp=0): return (row,14,note,inst,vol,fx,fp)
def PAD(row, inst, note='A-4', vol=9): return (row,15,note,inst,vol,0,0)
def PNO(row, note, vol=26, chan=10, fx=0, fp=0): return (row,chan,note,22,vol,fx,fp)
def FT(row, note='A-1', vol=42): return (row,12,note,7,vol,0,0)
def OFF(row, chan, vol=0, fx=0xC, fp=0):  return (row,chan,'off',0,vol,fx,fp)

def hatrow(c,o):
    r=[]
    if o=='closed':
        for i in range(16): r.append(H(i*4, 22 if i%2 else 15))
    elif o=='16':
        for off,vl in [(0,14),(2,9),(4,20),(6,9),(8,14),(10,9),(12,20),(14,9)]: r.append(H(off,vl))
    elif o=='open4':
        for off in [4,12]: r.append(H(off,15,True))
    elif o=='openlast':
        r.append(H(12,16,True))
    elif o=='roll':
        r.append(H(4,15,True)); r.append(H(12,16,True)); r.append(H(14,12)); r.append(H(15,14))
    c+=r

def grad_note(inst_by_bar, bar, default):
    n = inst_by_bar[bar] if bar < len(inst_by_bar) else default
    return n

# ---------------- intro P0 : pad + swoosh riser + stab taps ----------------
def p_intro():
    c=[]
    c.append(PAD(0, 10, 'A-4', 8))
    # riser = bass_s gliss up, 8vaC from A2 to A4 across 40 rows
    base = 10+7*12+9  # A-2 -> 33
    for i in range(41):
        note = min(33 + i//2, 33+24)
        c.append((i, 6, note, 7, 24, 0x8, 0xC))
    c += [OFF(41,6)]
    c += [ST(16,'A-4',12,20), ST(28,'A-4',12,16), ST(40,'A-4',12,22), ST(52,'A-4',12,16)]
    return c

# ---------------- intro2 P1 : beat + 16 hats, minimal bass, piano motif seed
def p_intro2():
    c=[]
    for r in [0,8,16,24,32,40,48,56]: c.append(K(r))
    hatrow(c,'16')
    c += [B(0,'A-2',8,40), B(8,'E-2',8,38), B(32,'G-2',8,38), B(56,'G-2',8,38)]
    c += [ST(32,'A-4',12,18)]
    # motif seed pickup
    c += [PNO(52,'B-4',16), PNO(56,'A-4',26), PNO(60,'B-4',20)]
    return c

# ---------------- verse P2/P3 (chord-pattern per 2-bar)
def p_verse(vary):
    c=[]
    for r in [0,8,16,24,32,40,48,56]: c.append(K(r))
    for r in [16,48]: c.append(SN(r, 34 if vary==0 else 30))
    hatrow(c,'closed'); hatrow(c, 'openlast' if vary in (0,3) else 'open4')
    # bass
    roots = {0:8, 16:16, 32:24, 48:24}
    barbi = {
      (0,'Am'): [ (0,'A-2'),(2,'A-2'),(4,'E-3'),(6,'A-2'),(8,'A-2'),(10,'G-2'),(12,'E-3'),(14,'G-2') ],
      (1,'F'):  [ (16,'F-2'),(18,'F-2'),(20,'C-3'),(22,'F-2'),(24,'F-2'),(26,'E-2'),(28,'C-3'),(30,'E-2') ],
      (2,'C'):  [ (32,'C-2'),(34,'C-2'),(36,'G-2'),(38,'C-2'),(40,'C-2'),(42,'G-2'),(44,'E-3'),(46,'G-2') ],
      (3,'G'):  [ (48,'G-2'),(50,'G-2'),(52,'D-3'),(54,'G-2'),(56,'G-2'),(58,'G-2'),(60,'E-3'),(62,'G-2') ],
    }
    InstMap = [ [8,8,8,7,8,8,7,8], [8,8,7,8,8,8,8,7], [9,9,9,8,9,9,8,8], [8,8,8,8,8,8,9,9] ]
    for bi,(key,steps) in enumerate(barbi.items()):
        insts = InstMap[(bi + (1 if vary>=2 else 0)) % 4]
        for k,(rw,nt) in enumerate(steps):
            v = 46 if (rw%8)==0 else 40
            c.append(B(rw, nt, insts[k], v))
    # extra turnarounds
    if vary==1:
        c += [B(62,'B-2',8,40), B(63,'B-2',8,44)]
    if vary==3:
        c += [B(56,'G-2',8,44), B(58,'B-2',8,40), B(60,'G-2',8,42), B(62,'B-2',8,42)]
    # stabs
    c += [ST(0,'A-4',11,26, 7, 0x3, 0x10)]
    c += [ST(32,'C-4',13,24)]
    if vary==1: c += [ST(56,'G-3',12,22)]
    if vary==3: c += [ST(56,'G-3',12,22), ST(58,'B-3',12,22)]
    # pads sustain full pattern
    pad_inst = {0:10, 1:19, 2:20, 3:10}[vary]
    c.append(PAD(0, pad_inst, 'A-4' if vary!=2 else 'C-5', 8))
    # piano answers B: offbeat Am arp (bars C,D)
    c += [PNO(36,'E-5',15), PNO(40,'C-5',15), PNO(44,'B-4',15), PNO(48,'A-4',14)]
    if vary==3:
        c += [PNO(64-8+0,'E-5',15,10,0x3,0x10)]  # will replace at 56? keep
    return c
EOF
